import { describe, expect, mock, test } from 'claude-code/testing'
import type { On } from 'claude-code'
import type { Engine } from 'claude-code/testing'

import { DOT, hudLines, sextSprite, sidebar, spriteCells, SW, textOf } from './tui'
import type { Hud, View } from './tui'
// A copy of docs/design/term/fixture/pen.json , generated by board/scripts/gen-pen.py.
import { PEN_D_ROW2_COLORS, PEN_FIXTURE as pen } from './pen-fixture'

// Slice 2 of docs/plan/2026-10-23-board-tui-judge.md: the fixture mode (D-4) and the fold (D-5).
const FIX = pen as unknown as View & { hud: Hud }
// 40 列侧栏(owner 10.23 的 dockColumns):框 + 内边距 4 格，内容 36 格。
const W = 36
const rows = (fold: boolean) => sidebar(FIX, W, fold).map(d => textOf(d.row))

describe('board tui: drawn as docs/design/term/tui.py', () => {
  test('every row is W + 4 cells, framed in ╭╮ │ ╰╯', () => {
    const r = rows(false)
    expect(r[0]).toBe(`╭${'─'.repeat(W + 2)}╮`)
    expect(r[r.length - 1]).toBe(`╰${'─'.repeat(W + 2)}╯`)
    for (const x of r.slice(1, -1)) expect(x.startsWith('│ ') && x.endsWith(' │')).toBe(true)
  })

  test('open all: the .pen text in order, titles left, sources flush right', () => {
    const r = rows(false).map(x => x.slice(2, -2))
    expect(r[1]!.trimEnd()).toBe(' claude-mods                    68%')
    expect(r.includes(`谁在跑 · 3${' '.repeat(W - 10 - 19)}delegate + 子 agent`)).toBe(true)
    const order = ['谁在跑 · 3', '任务条 · 本会话计划', '下一步', 'GOAL · 17/25', '待拍板 · 2', 'TODO · 11 未勾', 'ROADMAP · 进行 2', '最近提交 · 5', '今日用量 · 42.1M / 300M']
    const at = order.map(t => r.findIndex(x => x.startsWith(t)))
    expect(at.every((v, i) => v > 0 && (i === 0 || v > at[i - 1]!))).toBe(true)
    expect(r.some(x => x.startsWith('· wt-reap 接 disk-watch'))).toBe(true)
    expect(r.some(x => x.startsWith('⚠  终端 reduced-motion 要不要做'))).toBe(true)
    expect(r.some(x => x.trimEnd().endsWith('2.7M') && x.startsWith('sol'))).toBe(true)
    expect(r.some(x => x.startsWith(' 下一步:wt-reap 接 disk-watch'))).toBe(true)  // 40 列稿：现在在 / 下一步拆两行，不截
    expect(r.some(x => x.includes(' heavy · 62k · 2m10s'))).toBe(true)
    expect(r.some(x => x.trimEnd().endsWith('▬ ctx 41%'))).toBe(true)
    expect(r.length).toBe(61)
  })

  test('/board open folds the six to ▸ titles; 谁在跑, 任务条, 待拍板 keep their bodies', () => {
    const r = rows(true).map(x => x.slice(2, -2).trimEnd())
    for (const t of ['▸ 下一步', '▸ GOAL · 17/25', '▸ TODO · 11 未勾', '▸ ROADMAP', '▸ 最近提交 · 5', '▸ 今日用量']) expect(r.some(x => x.startsWith(t)), t).toBe(true)
    expect(r.some(x => x.includes('wt-reap 接 disk-watch') && !x.includes('下一步:'))).toBe(false)
    expect(r.some(x => x.startsWith('⚠  vhdx 停机授权谁来记'))).toBe(true)
    // folded neighbours sit with no blank between; a folded block next to an open one keeps it
    const i = r.findIndex(x => x.startsWith('▸ TODO'))
    expect(r.slice(i, i + 4).every(x => x.startsWith('▸ '))).toBe(true)
    expect(r[r.findIndex(x => x.startsWith('待拍板')) - 1]).toBe('')
    expect(r.length).toBe(39)
  })

  test('the task bar is a purple gradient over track, the card bar green / yellow / track', () => {
    const band = sidebar(FIX, W, false).find(d => d.key === 'task-band')!.row
    const cols = band.slice(2, -2).map(s => s.fg)
    expect(cols[0]).toBe('#6d28d9')
    expect(cols[16]).toBe('#c4b5fd')
    expect(cols[17]).toBe('#2a2640')
    const card = sidebar(FIX, W, false).find(d => d.key === 'card-5')!.row
    const n = (c: string) => card.filter(s => s.fg === c).reduce((k, s) => k + [...s.t].length, 0)
    expect([n('#22c55e'), n('#eab308'), n('#2a2640')]).toEqual([19, 5, 10])
  })

  test('D lines: l1 / l2, ↑N bold, ☎ green, one 5-cell sextant crab per helper', () => {
    const [l1, l2] = hudLines(FIX.hud)
    expect(textOf(l1)).toBe(' Opus 5.5·low │ claude-mods ⎇ master* ↑417 │ ctx ▆▆▆▆▆▆ 24% │ 5h ▆▆▆▆▆▆ 44% 59m │ 周 30%  ☎')
    expect(textOf(l2)).toBe(' ▶ 任务 ▆▆▆▆▆▆▆▆ 3/6 GWT-7 先红 │ 🬫🬵🬹🬗🬂 🬫🬹🬹🬗🬋 🬋🬊🬌🬰🬹 3 在跑 │ ◷ 58m')
    expect(l1.find(s => s.t === '↑417')).toEqual({ t: '↑417', fg: '#eab308', bg: '#0c0c0c', b: true })
    expect(l1.find(s => s.t.includes('☎'))?.fg).toBe('#22c55e')
    const crab = (c: string) => sextSprite(c).map(x => `${x.t}${x.fg}${x.bg ?? ''}`).join('')
    const drawn = l2.map(x => `${x.t}${x.fg}${x.bg === '#0c0c0c' ? '' : (x.bg ?? '')}`).join('')
    for (const c of ['heavy', 'medium', 'minimax']) expect(drawn.includes(crab(c)), c).toBe(true)
  })
})

// The fixture through the engine: no git, no agent list, the file's text in the pane and above the prompt.
const FIXTURE_PATH = '/fx/pen.json'
type Calls = { runs: string[]; agentList: number }
function fixtureWorld(on: On, opts: { ownOpen?: boolean } = {}): Calls {
  const calls: Calls = { runs: [], agentList: 0 }
  mock.env(on, { HOME: '/home/t', BOARD_FIXTURE: FIXTURE_PATH })
  mock.store(on)
  mock.clock(on, { now: 1_000_000 })
  on('session.start', (_, e) => ({ cwd: e.cwd }))
  on('session.cwd', () => ({ value: '/home/t/repos/myapp' }))
  on('session.id', async () => ({ value: 'sid1' }) as never)
  on('settings.read', async () => ({ value: { enabledPlugins: {} } }) as never)
  on('command.register', (_, e) => ({ value: { command: e.name } }))
  on('tool.register', async () => ({ value: { tool: 'mcp__board__plan' } }) as never)
  on('agent.list', async () => {
    calls.agentList += 1
    return { value: [] } as never
  })
  if (!opts.ownOpen) on('ui.open', async () => ({ value: { isPlaced: true } }) as never)
  on('ui.render', { component: 'AbovePrompt' }, async ($, e) => {
    const { Box } = $.ui.resolve(e)
    return <Box flexDirection="column" />
  })
  on('fs.stat', () => {
    throw new Error('ENOENT')
  })
  on('fs.read', (_, e) => {
    if (e.path === FIXTURE_PATH) return { value: JSON.stringify(pen) }
    throw new Error(`ENOENT ${e.path}`)
  })
  on('fs.list', () => ({ value: [] }))
  on('process.run', (_, e) => {
    calls.runs.push((e as { argv?: string[] }).argv?.join(' ') ?? '')
    return { value: { exitCode: 0, stdout: 'zzz', stderr: '', isStdoutTruncated: false, isStderrTruncated: false } }
  })
  return calls
}
const open = ($: Engine, args: string) => $.command.run({ command: 'board', args, presentation: { isFullscreen: true, columns: 170 } } as never)
async function paneText($: Engine): Promise<string[]> {
  const ui = await $.ui.mount({ plugin: 'board', surface: 'terminal', component: 'Pane', requestId: 'board', props: { bodyColumns: 40 } } as never)
  const t = (await ui.findAll({ type: 'Text' })).map(el => el.text ?? '').filter(x => x.length > 1 && /^[│╭╰]/.test(x))
  await ui.unmount()
  return [...new Set(t)]
}

describe('board BOARD_FIXTURE', () => {
  test('/board open all: the pane is the fixture, row for row; no git, no agent list', async ($, on) => {
    const calls = fixtureWorld(on)
    await $.session.start({ source: 'startup', cwd: '/home/t/repos/myapp', surface: 'terminal', isInteractive: true } as never)
    await open($, 'open all')
    const shown = await paneText($)
    expect(shown).toEqual([...new Set(rows(false))])
    expect(calls.runs.some(r => r.startsWith('git'))).toBe(false)
    expect(calls.agentList).toBe(0)
  })

  test('/board open: folded', async ($, on) => {
    fixtureWorld(on)
    await $.session.start({ source: 'startup', cwd: '/home/t/repos/myapp', surface: 'terminal', isInteractive: true } as never)
    await open($, 'open')
    expect(await paneText($)).toEqual([...new Set(rows(true))])
  })

  // 10.23 事件日志：别的面板后开就占住侧栏;已开着的 id 再 open 只改标题。/board open 要把 board 换到前面。
  test('/board open when board sits behind another pane: closes and reopens it so it is the one shown', async ($, on) => {
    fixtureWorld(on, { ownOpen: true })
    const ui: string[] = []
    let front = 'chat-inventory'
    on('ui.open', async ($, e) => {
      ui.push(`open ${(e as { id: string }).id}`)
      front = (e as { id: string }).id === 'board' && ui.includes('close board') ? 'board' : front
      return { value: { isPlaced: true } } as never
    })
    on('ui.close', async ($, e) => {
      ui.push(`close ${(e as { id: string }).id}`)
      return { value: undefined } as never
    })
    on('ui.panes', async () => ({ value: [{ id: 'board', title: '进度', isShown: front === 'board', isFocused: false, isPlaced: true }] }) as never)
    await $.session.start({ source: 'startup', cwd: '/home/t/repos/myapp', surface: 'terminal', isInteractive: true } as never)
    await open($, 'open')
    expect(ui).toEqual(['open board', 'close board', 'open board'])
    expect(front).toBe('board')
    ui.length = 0
    await open($, 'open')
    expect(ui, 'already in front: just the open').toEqual(['open board'])
  })

  test('the two lines above the prompt come from the fixture too', async ($, on) => {
    const calls = fixtureWorld(on)
    await $.session.start({ source: 'startup', cwd: '/home/t/repos/myapp', surface: 'terminal', isInteractive: true } as never)
    const hud = await $.ui.mount({ plugin: 'board', surface: 'terminal', component: 'AbovePrompt', props: { isWorking: false, hasSurvey: false, maxRows: 10, bodyColumns: 170 } } as never)
    const t = (await hud.findAll({ type: 'Text' })).map(el => el.text ?? '')
    await hud.unmount()
    expect(t.some(x => x.startsWith(' Opus 5.5·low │ claude-mods ⎇ master* ↑417'))).toBe(true)
    expect(t.some(x => x === ' ▶ 任务 ▆▆▆▆▆▆▆▆ 3/6 GWT-7 先红 │ 🬫🬵🬹🬗🬂 🬫🬹🬹🬗🬋 🬋🬊🬌🬰🬹 3 在跑 │ ◷ 58m')).toBe(true)
    expect(calls.runs.some(r => r.startsWith('git'))).toBe(false)
  })
})

describe('board tui: a costume the .pen has no sprite for (all 8 are in it since 10.23 晚)', () => {
  test('the old 8+2-column sprite fits SW columns: prop dropped, body starts at column 0', () => {
    const rows = ['..tttt..KK', '.cccccc.kg', '.ckccck..b', 'cccccccc..', '.cccccc...', '.c.cc.c...']
    const cells = spriteCells({ costume: 'not-in-pen', name: 'x', meta: '', rows, colors: { t: '#111111', c: '#222222', k: '#333333', K: '#444444', g: '#555555', b: '#666666' } } as never)
    expect(cells.every(r => r.length === SW)).toBe(true)
    const used = new Set(cells.flat().flat().filter(Boolean))
    expect(used.has('#444444') || used.has('#555555') || used.has('#666666')).toBe(false)
    expect(cells[2][0][0]).toBe('#222222')
  })
})

// 每一种 helper 点色都要是闸认得的颜色(tui-judge.py --palette:D 稿第 2 行的块色 + 豁免放行色)。
// 新加一种造型而 D 稿没补它的帽色，这里就红。
describe('line-2 crabs: every costume\'s sextant colours are in the D sheet', () => {
  for (const c of Object.keys(DOT))
    test(c, () => {
      for (const s of sextSprite(c)) for (const h of [s.fg, s.bg].filter(Boolean)) expect(PEN_D_ROW2_COLORS).toContain(h!.toLowerCase())
    })
})

describe('helper dots: every DOT hat colour is in the D sheet', () => {
  for (const [costume, hex] of Object.entries(DOT))
    test(`${costume} ${hex}`, () => {
      expect(PEN_D_ROW2_COLORS).toContain(hex.toLowerCase())
    })
})
